/**
 * De sleutels van Marokko in het Duits.
 *
 * Wordt deel voor deel vertaald. Wat hier staat is af; de rest valt terug op
 * het Nederlands tot het zover is.
 *
 * De regelval van het Nederlands blijft staan: één alinea daar is één alinea
 * hier. Dat is geen vormfetisj — een hoofdstuk van dit boek is opgebouwd uit
 * korte alinea’s met stiltes ertussen, en wie die samenvoegt haalt het tempo
 * eruit.
 *
 * Aanhalingstekens zijn de Duitse „ en “, de apostrof is overal de
 * typografische ’ en nooit de rechte: die breekt de string waar dit bestand
 * in staat.
 */
